/bin/sh -lc "cat > /work/plan.json << 'EOF'
{
  \"title\": \"Device Inventory and Beneficiary Support Dashboard\",
  \"subtitle\": \"Current stock, beneficiaries served, and coverage by disability type\",
  \"_mode\": \"dashboard\",
  \"panels\": [
    {
      \"id\": \"p1\",
      \"kind\": \"kpi\",
      \"title\": \"Current Stock Total\",
      \"sql\": \"SELECT COALESCE(SUM(CASE WHEN device_type = 'Braille kit' THEN balance_after WHEN device_type = 'Hearing aid' THEN balance_after WHEN device_type = 'Tricycle' THEN balance_after WHEN device_type = 'Wheelchair' THEN balance_after WHEN device_type = 'Crutches' THEN balance_after WHEN device_type = 'Walking stick' THEN balance_after WHEN device_type = 'Calipers' THEN balance_after END), 0) AS total_units FROM device_inventory d1 INNER JOIN (SELECT device_type, MAX(date) as max_date FROM device_inventory GROUP BY device_type) d2 ON d1.device_type = d2.device_type AND d1.date = d2.max_date\"
    },
    {
      \"id\": \"p2\",
      \"kind\": \"bar\",
      \"title\": \"Current Stock by Device Type\",
      \"sql\": \"SELECT device_type, balance_after AS value FROM device_inventory d1 INNER JOIN (SELECT device_type, MAX(date) as max_date FROM device_inventory GROUP BY device_type) d2 ON d1.device_type = d2.device_type AND d1.date = d2.max_date ORDER BY value DESC\"
    },
    {
      \"id\": \"p3\",
      \"kind\": \"bar\",
      \"title\": \"Beneficiaries by Disability Type\",
      \"sql\": \"SELECT \\\"Disability Type\\\", COUNT(*) AS beneficiaries_served FROM beneficiary_master WHERE \\\"Assistive Device Issued\\\" IS NOT NULL AND \\\"Assistive Device Issued\\\" "'!= '"'' GROUP BY \\\"Disability Type\\\" ORDER BY beneficiaries_served DESC\"
    },
    {
      \"id\": \"p4\",
      \"kind\": \"table\",
      \"title\": \"Summary Statistics\",
      \"sql\": \"WITH latest_stock AS (SELECT device_type, balance_after FROM device_inventory d1 INNER JOIN (SELECT device_type, MAX(date) as max_date FROM device_inventory GROUP BY device_type) d2 ON d1.device_type = d2.device_type AND d1.date = d2.max_date), total_beneficiaries AS (SELECT COUNT(*) AS n FROM beneficiary_master WHERE \\\"Assistive Device Issued\\\" IS NOT NULL AND \\\"Assistive Device Issued\\\" "'!= '"'') SELECT 'Total Current Stock' AS metric, COALESCE(SUM(balance_after), 0) AS value FROM latest_stock UNION ALL SELECT 'Total Beneficiaries Served' AS metric, total_beneficiaries.n FROM total_beneficiaries ORDER BY metric\"
    }
  ],
  \"narrative\": \"Dashboard showing device inventory status and beneficiary coverage\"
}
EOF
"

